// widget.h
class widget {
 public:
  widget();
  ~widget();
  widget(widget&&) noexcept;
  void draw() const;
 private:
  struct impl;                     // forward declaration only
  std::unique_ptr<impl> pimpl_;    // opaque pointer
};

using Renderer = std::variant<SoftwareRenderer, CairoRenderer, VulkanRenderer>;

class Circle {
 public:
  Circle(Renderer r, double radius) : r_(std::move(r)), radius_(radius) {}
  void draw() const {
    std::visit([this](const auto& impl) { impl.circle(radius_); }, r_);
  }
 private:
  Renderer r_;
  double radius_;
};

